'use strict';
// Pure metadata projection. Never execute workflow code or retain arbitrary response fields.
const COLLECTION = new Set(['ok', 'error', 'unknown']);
const EXECUTION = new Set(['canceled', 'crashed', 'error', 'new', 'running', 'success', 'unknown', 'waiting']);
const MODES = new Set(['real', 'sombra', 'interno']);
const CATEGORIES = new Set(['UTILITY', 'MARKETING', 'AUTHENTICATION']);
const TEMPLATE_STATUS = new Set(['APPROVED', 'PENDING', 'REJECTED', 'PAUSED', 'DISABLED', 'IN_APPEAL', 'PENDING_DELETION', 'DELETED', 'LIMIT_EXCEEDED']);
function iso(value) { return typeof value === 'string' && Number.isFinite(Date.parse(value)) ? new Date(value).toISOString() : null; }
function id(value) { return typeof value === 'string' && /^[A-Za-z0-9_-]{1,80}$/.test(value) ? value : null; }
function mode(value) { return typeof value === 'string' && MODES.has(value) ? value : 'unknown'; }
function retention(value) { return value === 'all' || value === 'none' ? value : 'unknown'; }
function response(raw) {
  if (!raw || typeof raw !== 'object') return {ok:false, code:'invalid_response'};
  const status = Number(raw.statusCode);
  if (!Number.isInteger(status)) return {ok:false, code:'transport_error'};
  if (status < 200 || status > 299) return {ok:false, code: status === 401 || status === 403 ? 'access_denied' : status === 404 ? 'not_found' : status === 429 ? 'rate_limited' : 'http_error'};
  let body = raw.body;
  if (typeof body === 'string') { try {body = JSON.parse(body);} catch (_) {return {ok:false,code:'invalid_json'};} }
  if (!body || typeof body !== 'object' || Array.isArray(body)) return {ok:false,code:'invalid_response'};
  return {ok:true, body};
}
function removeComments(source) {
  // Quote-aware stripping used only on allowlisted Config nodes; it is not an evaluator.
  let out='', quote=null;
  for (let i=0;i<source.length;i++) {
    const c=source[i], next=source[i+1];
    if (quote) { out+=c; if (c==='\\') {out+=next||'';i++;} else if (c===quote) quote=null; continue; }
    if (c==='\'' || c==='"' || c==='`') {quote=c;out+=c;continue;}
    if (c==='/' && next==='/') {while(i<source.length && source[i]!=='\n')i++;out+='\n';continue;}
    if (c==='/' && next==='*') {i+=2;while(i<source.length && !(source[i]==='*' && source[i+1]==='/'))i++;i++;out+=' ';continue;}
