function extractModes(nodes, specs) {
  return (specs || []).map(spec => {
    const matches=(nodes || []).filter(n=>n && n.name===spec.node);
    let value='unknown';
    if (matches.length===1) {
      const p=matches[0].parameters || {};
      if (spec.type==='set') {
        const values=(p.assignments?.assignments || []).filter(a=>a.name===spec.key && a.type==='string');
        if(values.length===1)value=mode(values[0].value);
      } else if(typeof p.jsCode==='string') {
        const code=removeComments(p.jsCode);
        if (spec.type==='cart_const') {
          const found=[...code.matchAll(/\bconst\s+MODO\s*=\s*(['"])(real|sombra|interno)\1\s*;/g)];
          const writes=[...code.matchAll(/\bMODO\s*=/g)];
          if(found.length===1 && writes.length===1)value=mode(found[0][2]);
        } else if(spec.type==='pix_json') {
          const match=code.match(/^\s*return\s*\[\s*\{\s*json\s*:\s*(\{[\s\S]*\})\s*\}\s*\]\s*;?\s*$/);
          if(match) {try {value=mode(JSON.parse(match[1]).modo);} catch (_) {}}
        } else if(spec.type==='receiver_brand' && ['fish','aristo'].includes(spec.brand)) {
          const object=code.match(/\bconst\s+AUTO\s*=\s*\{([\s\S]*?)\n\s*\};/);
          if(object) {
            const re=new RegExp('\\b'+spec.brand+'\\s*:\\s*\\{\\s*modo\\s*:\\s*([\'\"])(real|sombra|interno)\\1');
            const found=object[1].match(re);
            const mutations=code.match(/\bAUTO(?:\s*\[[^\]]*\]|\s*\.\s*\w+)+\s*=/g);
            if(found && !mutations)value=mode(found[2]);
