function baseWorkflow(descriptor, previous, checkedAt) {
  return {key:descriptor.key,brand:descriptor.brand,channel:descriptor.channel,label:descriptor.label,
    checked_at:iso(checkedAt),last_good_at:iso(previous?.last_good_at),collection_status:'unknown',collection_error_code:null,
    active:null,published:null,has_unpublished_changes:null,version_id:null,active_version_id:null,
    mode_source:descriptor.mode_source || 'none',modes:(descriptor.mode_specs || []).map(s=>({key:s.key,value:'unknown'})),
    retention:{success:'unknown',error:'unknown'},last_retained_execution:null};
}
function clearWorkflow(state, error) {
  return {...state,collection_status:'error',collection_error_code:error,active:null,published:null,has_unpublished_changes:null,
    version_id:null,active_version_id:null,modes:state.modes.map(s=>({key:s.key,value:'unknown'})),
    retention:{success:'unknown',error:'unknown'},last_retained_execution:null};
}
function workflowMetadata(descriptor, raw, previous, checkedAt) {
  let state=baseWorkflow(descriptor, previous, checkedAt);
  const r=response(raw); if(!r.ok)return {descriptor,state:clearWorkflow(state,r.code),metadata_ok:false};
  const w=r.body;
  if(w.id!==descriptor.id || typeof w.active!=='boolean' || !Array.isArray(w.nodes) || !w.settings || typeof w.settings!=='object')
    return {descriptor,state:clearWorkflow(state,'invalid_workflow'),metadata_ok:false};
  const publishedId=id(w.activeVersionId), active=w.activeVersion;
  if(w.active && (!publishedId || active?.versionId!==publishedId || active?.workflowId!==descriptor.id || !Array.isArray(active?.nodes)))
    return {descriptor,state:clearWorkflow(state,'published_version_unavailable'),metadata_ok:false};
  const nodes=w.active ? active.nodes : w.nodes;
  state={...state,active:w.active,published:!!publishedId,has_unpublished_changes:publishedId ? publishedId!==w.versionId : null,
    version_id:id(w.versionId),active_version_id:publishedId,modes:extractModes(nodes,descriptor.mode_specs),
    retention:{success:retention(w.settings.saveDataSuccessExecution),error:retention(w.settings.saveDataErrorExecution)}};
  return {descriptor,state,metadata_ok:true};
