function workflowExecution(partial, raw) {
  if(!partial.metadata_ok)return partial.state;
  const r=response(raw); if(!r.ok)return clearWorkflow(partial.state,r.code);
  if(!Array.isArray(r.body.data))return clearWorkflow(partial.state,'invalid_execution_list');
  // The request is limit=1&includeData=false; whitelist projection tolerates irrelevant unknown keys.
  if(r.body.data.length>1)return clearWorkflow(partial.state,'invalid_execution_list');
  const e=r.body.data[0]; let execution=null;
  if(e) {
    const startedAt=iso(e.startedAt);
    // A new execution may not have started yet; preserve explicit nulls, never invent a time.
    const identityPresent=typeof e.id==='string' || Number.isSafeInteger(e.id);
    const notStarted=e.status==='new' && e.startedAt===null && e.stoppedAt===null && identityPresent;
    if(String(e.workflowId)!==partial.descriptor.id || !id(String(e.id)) || !EXECUTION.has(e.status) || (!startedAt && !notStarted))
      return clearWorkflow(partial.state,'invalid_execution_metadata');
    execution={id:String(e.id),status:e.status,started_at:startedAt,stopped_at:iso(e.stoppedAt)};
  }
  return {...partial.state,collection_status:'ok',collection_error_code:null,last_good_at:partial.state.checked_at,last_retained_execution:execution};
}
function templateMetadata(descriptor, raw, previous, checkedAt) {
  const state={key:descriptor.key,brand:descriptor.brand,channel:'whatsapp',piece:descriptor.piece,usage:descriptor.usage,
    id:descriptor.id,name:descriptor.name,language:descriptor.language,expected_category:descriptor.expected_category,
    checked_at:iso(checkedAt),last_good_at:iso(previous?.last_good_at),collection_status:'unknown',collection_error_code:null,
    status:null,category:null,category_matches_expected:null};
  const r=response(raw); if(!r.ok)return {...state,collection_status:'error',collection_error_code:r.code};
  const t=r.body;
  if(String(t.id)!==descriptor.id || t.name!==descriptor.name || t.language!==descriptor.language)
    return {...state,collection_status:'error',collection_error_code:'template_identity_mismatch'};
  if(!CATEGORIES.has(t.category) || !TEMPLATE_STATUS.has(t.status))
    return {...state,collection_status:'error',collection_error_code:'unknown_template_state'};
  return {...state,collection_status:'ok',last_good_at:state.checked_at,status:t.status,category:t.category,category_matches_expected:t.category===descriptor.expected_category};
}
function buildSnapshot(rows, capturedAt, collectionMode='automatic') {
  const workflows=rows.filter(r=>r.kind==='workflow').map(r=>r.value).sort((a,b)=>a.key.localeCompare(b.key));
  const templates=rows.filter(r=>r.kind==='template').map(r=>r.value).sort((a,b)=>a.key.localeCompare(b.key));
  if(new Set(workflows.map(x=>x.key)).size!==workflows.length || new Set(templates.map(x=>x.key)).size!==templates.length)
    throw new Error('duplicate_snapshot_key');
  if(!['manual','automatic'].includes(collectionMode))throw new Error('invalid_collection_mode');
  return {schema_version:1,collection_mode:collectionMode,generated_at:iso(capturedAt),refresh_interval_seconds:collectionMode==='automatic'?300:0,stale_after_seconds:900,workflows,templates};
}

